INSERT INTO feature VALUES('ordered-algebras','theory','One law checker for ordered semirings',NULL,'partial','notable',NULL,'One signature of an ordered semiring, a carrier with an order, a zero, a one, an addition and a multiplication, and one checker that decides sixteen laws on it: the semiring laws, the laws of the order, and the monotonicity of both operations. It reads every tuple of a finite carrier and every tuple of the elements an infinite one generates, and a law that fails returns the instance, the law and the elements that break it; an operation past the represented elements leaves its law undecided, apart from a broken one. The usage semiring {0, 1, ω} passes on its whole carrier, and the core checker''s access rules add and compare the uses of a held value in it; the hold and capability grades break the unit of addition without its zero. The max-plus semiring and the Lawvere quantale pass over exact dyadics, and the cells census composes each fusion cell''s bound in the Lawvere quantale. Lattices, quantales beyond the Lawvere one, Galois connections and the convolution semialgebra over shapes are not checked yet.','theory-ordered-algebras','crates/theory-ordered-algebras/tests/laws.rs crates/core-term/tests/grades.rs crates/surface-dispatcher/tests/distances.rs','crate-tests','#4997');
